"""Deterministic synthetic fixtures; no AI art is generated by these tests."""
import json
from pathlib import Path
import tempfile
import unittest

from PIL import Image
from export_assets import export, pixels


class ExportTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.spec = {
            'version': 1, 'preview_scale': 3,
            'families': {'icon': {'canvas': [4, 4], 'anchors': {'foot': [2, 4]}}},
            'assets': [{'id': 'a', 'family': 'icon', 'source': 'a.png',
                        'source_anchors': {'foot': [8, 16]}}],
        }
        logical = Image.new('RGBA', (4, 4))
        logical.putpixel((1, 1), (22, 44, 66, 255))
        logical.putpixel((2, 2), (77, 99, 111, 255))
        self.logical = logical
        logical.resize((16, 16), Image.Resampling.NEAREST).save(self.root/'a.png')

    def run_export(self):
        path = self.root/'spec.json'
        path.write_text(json.dumps(self.spec), encoding='utf-8')
        return export(path, self.root/'out')

    def reject(self, fragment):
        with self.assertRaisesRegex(ValueError, fragment):
            self.run_export()
        self.assertFalse((self.root/'out').exists())

    def test_exact_pixels_anchors_and_preview_blocks(self):
        result = self.run_export()
        with Image.open(self.root/'out/a.png') as actual:
            self.assertEqual(actual.tobytes(), self.logical.tobytes())
        with Image.open(self.root/'out/previews/a@3x.png') as preview:
            expected = self.logical.resize((12, 12), Image.Resampling.NEAREST)
            self.assertEqual(preview.tobytes(), expected.tobytes())
        self.assertEqual(result['assets'][0]['anchors']['foot'], [2, 4])
        self.assertEqual(result['assets'][0]['review']['in_game'], 'not_run')

    def test_aspect_ratio_is_not_stretched(self):
        self.spec['families']['icon']['canvas'] = [4, 3]
        self.reject('aspect ratio')

    def test_alpha_requires_explicit_policy(self):
        Image.new('RGBA', (16, 16), (20, 30, 40, 120)).save(self.root/'a.png')
        self.reject('semi-transparent')

    def test_explicit_threshold_keeps_rgb(self):
        Image.new('RGBA', (16, 16), (20, 30, 40, 120)).save(self.root/'a.png')
        self.spec['families']['icon']['alpha_threshold'] = 100
        self.run_export()
        with Image.open(self.root/'out/a.png') as result:
            self.assertEqual(result.getpixel((0, 0)), (20, 30, 40, 255))

    def test_palette_is_shared_and_exact(self):
        self.spec['families']['icon'].update(colors='palette', palette=['#102030'])
        result = self.run_export()
        self.assertEqual(result['assets'][0]['colors'], 1)
        with Image.open(self.root/'out/a.png') as image:
            self.assertEqual({p[:3] for p in pixels(image) if p[3]}, {(16, 32, 48)})

    def test_anchor_drift_rejected(self):
        self.spec['assets'][0]['source_anchors']['foot'] = [0, 0]
        self.reject('anchor mismatch')

    def test_group_sampling_mismatch_rejected(self):
        self.spec['assets'][0]['group'] = 'animation'
        Image.new('RGBA', (32, 32), (10, 20, 30, 255)).save(self.root/'b.png')
        self.spec['assets'].append({'id': 'b', 'family': 'icon', 'source': 'b.png', 'group': 'animation'})
        self.reject('group transform mismatch')

    def test_sheet_crop_uses_full_source_anchor_coordinates(self):
        sheet = Image.new('RGBA', (32, 16))
        with Image.open(self.root/'a.png') as image:
            sheet.paste(image, (16, 0))
        sheet.save(self.root/'sheet.png')
        self.spec['assets'][0].update(source='sheet.png', source_rect=[16, 0, 32, 16],
                                      source_anchors={'foot': [24, 16]})
        self.run_export()
        with Image.open(self.root/'out/a.png') as result:
            self.assertEqual(result.tobytes(), self.logical.tobytes())

    def test_subject_scale_rejected_despite_matching_canvas(self):
        self.spec['families']['icon']['bbox_size'] = {'min': [3, 3]}
        self.reject('subject bbox')

    def test_does_not_overwrite_existing_output(self):
        self.run_export()
        before = (self.root/'out/a.png').read_bytes()
        with self.assertRaisesRegex(ValueError, 'already exists'):
            self.run_export()
        self.assertEqual(before, (self.root/'out/a.png').read_bytes())

    def test_rectangular_noninteger_sampling_preserves_source_colors(self):
        Image.new('RGBA', (15, 10), (31, 41, 59, 255)).save(self.root/'a.png')
        self.spec['families']['icon'].update(canvas=[6, 4], anchors={})
        result = self.run_export()
        self.assertEqual(result['assets'][0]['source_pixels_per_logical_pixel'], 2.5)
        with Image.open(self.root/'out/a.png') as image:
            self.assertEqual(image.size, (6, 4))
            self.assertEqual(set(pixels(image)), {(31, 41, 59, 255)})

    def test_effect_can_preserve_alpha(self):
        Image.new('RGBA', (16, 16), (20, 30, 40, 120)).save(self.root/'a.png')
        self.spec['families']['icon']['alpha'] = 'preserve'
        result = self.run_export()
        self.assertEqual(result['assets'][0]['alpha_values'], [120])

    def test_empty_layer_requires_explicit_permission(self):
        Image.new('RGBA', (16, 16)).save(self.root/'a.png')
        self.reject('empty sprite')
        self.spec['families']['icon']['allow_empty'] = True
        result = self.run_export()
        self.assertIsNone(result['assets'][0]['bbox'])


if __name__ == '__main__':
    unittest.main()
